'use strict';
const L=(en,id,zh)=>[en,id,zh][langIndex()];
const book=()=>BOOKS[p().book||'pet'];
const artPath=i=>book().images[i];
function rememberBook(){const pr=p();if(!pr)return;pr.book=pr.book||'pet';pr.difficulty=pr.difficulty||'standard';pr.books=pr.books||{};pr.books[pr.book+':'+pr.difficulty]={scene:pr.scene,done:[...pr.done],answers:[...pr.answers],shared:pr.shared,activity:pr.activity||'',check:pr.check??-1};}
function prepareBook(){const pr=p();pr.book=BOOKS[pr.book]?pr.book:'pet';if(pr.difficulty&&pr.difficulty!=='standard'){rememberBook();const saved=pr.books[pr.book+':standard']||{scene:0,done:[],answers:['','',''],shared:false,activity:'',check:-1};Object.assign(pr,{...saved,done:[...saved.done],answers:[...saved.answers],difficulty:'standard'});}pr.difficulty='standard';const b=book();STORY.splice(0,STORY.length,...b.editions.standard);for(const lang of ['en','id','zh'])SCENE_TITLES[lang]=b.titles[lang];STRINGS.storyName=b.title;STRINGS.bookTitle=b.title;STRINGS.prompts=b.prompts;STRINGS.frames=b.frames;pr.scene=Math.min(pr.scene,STORY.length-1);pr.done=pr.done.filter(i=>i<STORY.length);}
function switchBook(id,difficulty='standard',redraw=true){if(!BOOKS[id])return;const pr=p();difficulty='standard';if(pr.book===id&&pr.difficulty===difficulty){prepareBook();return}stop();rememberBook();pr.book=id;pr.difficulty=difficulty;const saved=pr.books[id+':'+difficulty]||{scene:0,done:[],answers:['','',''],shared:false,activity:'',check:-1};Object.assign(pr,{scene:saved.scene,done:[...saved.done],answers:[...saved.answers],shared:saved.shared,activity:saved.activity||'',check:saved.check??-1});prepareBook();save();if(redraw)render();}
const oldHeader=header;
header=function(){oldHeader();$('#language').setAttribute('aria-label',L('Menu language','Bahasa menu','菜单语言'));$('#language').title=L('Menu language — separate from story translation','Bahasa menu — terpisah dari terjemahan cerita','菜单语言，与故事翻译分开设置');};
homeView=function(){return `<section class="welcome-hero"><div class="welcome-copy"><span class="eyebrow">${L('A LITTLE STORY. A WORLD TO DISCOVER.','CERITA KECIL. DUNIA UNTUK DIJELAJAHI.','小小故事，大大世界。')}</span><h1>${L('Big adventures.<br>Little steps.','Petualangan besar.<br>Langkah kecil.','大大的冒险。<br>小小的脚步。')}</h1><p>${L('Learn English with Ping, one story at a time. Listen, discover the meaning, and try something kind in your own world.','Belajar bahasa Inggris bersama Ping, satu cerita setiap kali. Dengarkan, pahami artinya, lalu coba kebaikan di duniamu.','和熊猫平平一起，一个故事一个故事地学英语。听一听，懂意思，再把善意带进生活。')}</p><a class="btn" href="#read">${L('Continue my story','Lanjutkan ceritaku','继续我的故事')} ↗</a><a class="quiet-link" href="#books">${L('Explore the story garden','Jelajahi taman cerita','探索故事花园')} ↓</a><div class="hero-tags"><span>✓ ${L('Beginner & Standard books','Buku Pemula & Standar','入门与标准绘本')}</span><span>✓ ${L('5 audio settings','5 pengaturan audio','5档语音设置')}</span><span>✓ ${L('Translation when you need it','Terjemahan saat dibutuhkan','需要时查看翻译')}</span></div></div><div class="welcome-picture"><img src="/assets/garden-4.webp" alt="Ping sharing a basket of vegetables with Popo while Brenda watches" fetchpriority="high"><span class="floating-note">${L('Let’s grow together!','Ayo tumbuh bersama!','一起成长吧！')}</span></div></section><section class="how-it-works"><h2>${L('A story is just the beginning','Cerita hanyalah permulaan','故事只是开始')}</h2><div>${[['01','Listen & repeat','Dengar & ulangi','听读模仿'],['02','Understand the meaning','Pahami artinya','理解意思'],['03','Make it your own','Ungkapkan dengan caramu','表达自己'],['04','Try it in real life','Coba di kehidupan nyata','用在生活中']].map(x=>`<span><b>${x[0]}</b>${x[langIndex()+1]}</span>`).join('')}</div></section>${collectionsView()}<section class="grownup-banner"><span class="seed-mark">🌱</span><div><h2>${L('Small moments. Meaningful learning.','Momen kecil. Pembelajaran bermakna.','小小的时刻，有意义的学习。')}</h2><p>${L('Read together for a few minutes. Let your child wonder, repeat, ask, and try. Every small step counts.','Baca bersama beberapa menit. Beri anak waktu untuk berpikir, mengulang, bertanya, dan mencoba. Setiap langkah kecil berarti.','每天一起读几分钟。让孩子思考、跟读、提问和尝试。每一小步都有意义。')}</p></div>${btn(L('For grown-ups','Untuk orang dewasa','给大人'),'adult','secondary')}</section>`;};
readView=function(){const scene=p().scene,done=p().done.includes(scene),b=book();return `<div class="reader-heading"><a href="#home" class="quiet-link">← ${L('Story garden','Taman cerita','故事花园')}</a><div><span class="eyebrow">${b.tag[langIndex()]}</span><h1>${b.title[langIndex()]}</h1></div>${btn('↗ '+t('share'),'share','secondary small')}</div>${learningChoices()}<div class="storybook"><section class="illustration-panel"><button class="illustration-button" data-action="art" aria-label="${L('Enlarge illustration','Perbesar gambar','放大插画')}"><img src="${artPath(scene)}" alt="${e(b.alt[scene])}" fetchpriority="high"></button><div class="picture-footer"><span>${L('Look, wonder, tell','Lihat, pikirkan, ceritakan','看看、想想、说说')}</span><span>${scene+1} / ${STORY.length}</span></div><p class="illustration-prompt">${L('What do you notice in this picture?','Apa yang kamu perhatikan dalam gambar ini?','你在这幅图里发现了什么？')}</p></section><article class="reading-card"><div class="reading-top"><div><span class="eyebrow">${t('scene')} ${scene+1}</span><h2>${SCENE_TITLES[state.lang][scene]}</h2></div><span aria-label="${done?t('done'):''}">${done?'⭐':'✦'}</span></div><div class="audio-bar">${btn('▶ '+t('play'),'play','')}${btn('Ⅱ','pause','secondary',`disabled aria-label="${t('pause')}"`)}${btn('■','stop','secondary small',`aria-label="${t('stop')}"`)}<label><span class="sr">${t('speed')}</span><select id="rate">${[.65,.85,1].map(v=>`<option value="${v}" ${rate===v?'selected':''}>${v}×</option>`).join('')}</select></label></div><div class="reading-body">${nativeLang()?`<div class="button-row">${btn(t(showMeaning?'hideMeaning':'meaning'),'meaning','soft small')}</div>`:''}${storyMarkup()}<p class="note">${L('Tap any reading chunk to hear it. Listen, then use the pause to try it yourself.','Ketuk potongan bacaan untuk mendengarnya. Dengarkan, lalu gunakan jeda untuk mencoba.','点按文字片段即可听读。听完后，利用停顿自己试着读。')}</p></div></article></div><div class="reader-actions">${btn('← '+t('previous'),'prev','secondary',scene===0?'disabled':'')}${btn((done?'✓ ':'')+t(done?'done':'markDone'),'complete',done?'soft':'')}${scene===STORY.length-1?`<a class="btn" href="#write">${L('Make it your own','Ungkapkan dengan caramu','表达自己')} →</a>`:btn(t('next')+' →','next','secondary')}</div><nav class="page-dots" aria-label="${t('chapters')}">${STORY.map((_,i)=>`<button data-action="scene" data-index="${i}" class="${scene===i?'current':''}" aria-current="${scene===i?'step':'false'}" aria-label="${e(SCENE_TITLES[state.lang][i])}">${p().done.includes(i)?'✓':i+1}</button>`).join('')}</nav><p class="note voice-note">${t('voiceNote')}</p><details class="edition-note"><summary>${L('About this story edition','Tentang edisi cerita ini','关于这个故事版本')}</summary><p>${e(b.credit)}</p><p>${L('Translation is a learning aid. The new adaptations and translations have not yet had an independent bilingual editorial review.','Terjemahan membantu belajar. Adaptasi dan terjemahan baru belum ditinjau editor dwibahasa independen.','翻译用于辅助学习。新的改编和译文尚未经过独立双语编辑审核。')}</p>${p().book==='pet'?`<p>${L('Original full recording — follows the original manuscript, not the adapted on-screen text.','Rekaman asli lengkap mengikuti naskah asli, bukan teks adaptasi di layar.','原版完整录音对应原稿，与屏幕上的改编文字不同。')}</p><audio controls preload="none" src="/assets/original-readthrough.mp3"></audio>`:''}</details>`;};
const originalWrite=writeView;
writeView=function(){const b=book();return `${checkView()}${originalWrite()}<section class="card next-activity"><h2>${L('Now take the story into your world','Bawa cerita ke duniamu','把故事带进生活')}</h2><a href="#activities" class="btn">${b.activity[langIndex()]} →</a></section>`;};
function checkView(){return `<section class="meaning-check card"><span class="eyebrow">${L('PAUSE & THINK','BERHENTI & PIKIRKAN','停一停，想一想')}</span><h2>${book().question[langIndex()]}</h2><div class="check-options">${book().options[langIndex()].map((o,i)=>`<button data-new="check" data-index="${i}" aria-pressed="${p().check===i}" class="${p().check===i?'chosen':''}">${e(o)}</button>`).join('')}</div><p role="status">${p().check===0?L('Yes! Now tell a grown-up why, in your own words.','Ya! Sekarang jelaskan alasannya dengan kata-katamu sendiri.','对！现在用自己的话告诉大人为什么。'):p().check>0?L('Have another look at the story. Think about what care means.','Baca lagi ceritanya. Pikirkan arti kepedulian.','再看看故事，想想关心是什么意思。'):L('Choose an answer, then explain your idea.','Pilih jawaban, lalu jelaskan idemu.','选一个答案，再说说你的想法。')}</p></section>`;}
const householdView=activityView;
let householdOpen=false;
activityView=function(){if(householdOpen)return `<div class="button-row">${btn(L('← Back to story activity','← Kembali ke kegiatan cerita','← 返回故事活动'),'storyActivity','secondary')}</div>${householdView()}`;return `${head(book().activity[langIndex()],book().title[langIndex()])}<div class="activity-layout"><img src="${book().images[book().images.length-1]}" alt="${e(book().alt[book().alt.length-1])}"><section class="card"><span class="eyebrow">${L('TRY IT TOGETHER','COBA BERSAMA','一起试试')}</span><h2>${L('A little action, a real connection','Tindakan kecil, hubungan nyata','小小行动，真实联系')}</h2><p>${book().instructions[langIndex()]}</p><label for="activityReflection">${L('What did you notice or do?','Apa yang kamu amati atau lakukan?','你观察到了什么，做了什么？')}</label><p class="note">${L('Write in any language, draw on paper, or tell a grown-up. Do not include private details.','Tulis dalam bahasa apa saja, gambar di kertas, atau ceritakan kepada orang dewasa. Jangan tulis informasi pribadi.','可以用任何语言写、在纸上画，或告诉大人。不要填写隐私信息。')}</p><textarea id="activityReflection" maxlength="2000" placeholder="${L('I noticed… / I helped by…','Aku melihat… / Aku membantu dengan…','我发现…… / 我帮助……')}">${e(p().activity||'')}</textarea><div class="button-row">${btn(L('Save my reflection','Simpan refleksiku','保存我的感想'),'saveReflection','')}<a class="btn secondary" href="#progress">${t('progress')} →</a></div><p class="note">${L('Celebrate noticing, trying, and caring. No perfect result needed.','Rayakan pengamatan, usaha, dan kepedulian. Tidak harus sempurna.','为观察、尝试和关心而高兴。不需要完美的结果。')}</p></section></div><section class="grownup-banner"><div><h3>${L('Optional family activity','Kegiatan keluarga opsional','可选家庭活动')}</h3><p>${L('Practise choices and saving with your existing household chore coins.','Latih pilihan dan menabung dengan koin tugas rumah yang sudah ada.','使用已有的家务积分练习选择和储蓄。')}</p></div>${btn(L('Open family rewards','Buka hadiah keluarga','打开家庭奖励'),'familyRewards','secondary')}</section>`;};
const originalProgress=progressView;
progressView=function(){return `<div class="current-book-label">${book().title[langIndex()]} · ${categoryLabel(book().category)}</div>${originalProgress()}<section class="card next-activity"><h2>${L('My real-world discovery','Penemuanku di dunia nyata','我在生活中的发现')}</h2><p class="writing-print">${e(p().activity||L('Try the story activity and add your reflection.','Coba kegiatan cerita dan tambahkan refleksimu.','试试故事活动，再写下你的感想。'))}</p><a class="btn secondary" href="#home">${L('Choose another story','Pilih cerita lain','选择另一个故事')}</a></section>`;};
adult=function(){modal(L('Growing with Ping','Tumbuh bersama Ping','和平平一起成长'),`<p>${L('Ping helps children practise English through illustrated stories, translation, their own ideas, and everyday actions. Sit together for a short session and follow your child’s curiosity.','Ping membantu anak berlatih bahasa Inggris melalui cerita bergambar, terjemahan, ide sendiri, dan tindakan sehari-hari. Duduk bersama sebentar dan ikuti rasa ingin tahu anak.','平平通过绘本、翻译、个人想法和日常行动帮助孩子练习英语。每天一起坐一小会儿，跟随孩子的好奇心。')}</p><ol class="guide-list"><li>${L('Choose a book from the Beginner or Standard collection. They contain different books. Then choose an audio level from 1–5 within your book.','Pilih buku dari koleksi Pemula atau Standar, lalu pilih tingkat audio 1–5. Setiap koleksi memiliki buku berbeda.','从入门或标准书架选择一本书，再选1–5档语音。两个书架收录不同的书。')}</li><li>${L('Listen and repeat. Ask what the story means; reveal or listen to the translation when useful.','Dengarkan dan ulangi. Tanyakan arti cerita; lihat atau dengar terjemahan bila perlu.','听读模仿。问问故事是什么意思；需要时查看或听翻译。')}</li><li>${L('Let your child give their own answer. Encourage speaking, drawing or writing, then try the activity together.','Biarkan anak menjawab sendiri. Dukung berbicara, menggambar, atau menulis, lalu coba kegiatan bersama.','让孩子自己回答。鼓励说、画或写，然后一起做活动。')}</li></ol><p class="notice">${L('Progress celebrates participation, not tested mastery. These learning editions and translations are ready to explore, but still need independent editorial review before a classroom rollout.','Kemajuan merayakan partisipasi, bukan penguasaan yang teruji. Edisi pembelajaran dan terjemahan ini masih memerlukan tinjauan editor independen sebelum digunakan luas di kelas.','进度表示参与情况，不代表经过测试的掌握程度。这些学习版本和译文在大规模课堂使用前仍需独立编辑审核。')}</p><h3>${L('Your family’s space','Ruang keluargamu','你们的家庭空间')}</h3><p>${t('privacy')}</p><div class="button-row">${btn(t('profiles'),'profiles','soft')}${btn(t('export'),'export','secondary')}${btn(t('import'),'import','secondary')}</div><h3>${L('Keep the books for offline reading','Simpan buku untuk dibaca luring','保存绘本以便离线阅读')}</h3><p>${L('Download all four books, illustrations, text, translations and the original pet recording (about 13 MB). Device read-aloud voices may require internet; offline speech is not guaranteed. Keep a backup of learner progress.','Unduh keempat buku, gambar, teks, terjemahan, dan rekaman asli cerita hewan (sekitar 13 MB). Suara perangkat mungkin memerlukan internet; suara luring tidak dijamin. Cadangkan kemajuan belajar.','下载四本书、插画、文字、译文和宠物故事原版录音（约13 MB）。设备朗读声音可能需要网络，无法保证离线语音。请备份学习进度。')}</p>${btn(t('download'),'offline','soft')}<p id="offlineStatus" role="status"></p><details class="edition-note"><summary>${L('Artwork and editions','Gambar dan edisi','插画与版本')}</summary><p>${BOOKS.pet.credit}</p><p>${BOOKS.garden.credit}</p><p>${BOOKS.colors.credit}</p><p>${BOOKS.exercise.credit}</p></details>`);};
document.addEventListener('click',ev=>{const el=ev.target.closest('[data-new]');if(el?.dataset.new==='check'){p().check=Number(el.dataset.index);save();render();}});
const originalAction=action;
action=async function(el){switch(el.dataset.action){case 'familyRewards':householdOpen=true;render();return;case 'storyActivity':householdOpen=false;render();return;case 'saveReflection':p().activity=$('#activityReflection').value;save();toast(t('saved'));return;}const result=await originalAction(el);if(route==='read'&&['prev','next','scene'].includes(el.dataset.action))history.replaceState(null,'','#read?book='+p().book+'&page='+(p().scene+1));return result};
document.addEventListener('input',ev=>{if(ev.target.id==='activityReflection'){p().activity=ev.target.value;save();}});
STRINGS.readerSub=['Listen, understand, and try it yourself.','Dengar, pahami, dan coba sendiri.','听一听，理解，再自己试试。'];
STRINGS.appVersion=['Ping learning edition · 3 illustrated books','Edisi belajar Ping · 3 buku bergambar','平平学习版 · 3本绘本'];
STRINGS.offlineReady=['Books downloaded. Text and images are available offline; device voices may still need internet.','Buku sudah diunduh. Teks dan gambar tersedia luring; suara perangkat mungkin tetap membutuhkan internet.','绘本已下载。文字和图片可离线使用；设备语音可能仍需网络。'];
// Better phrase boundaries preserve short units such as “a pet” and “in the garden”.
const oldPhraseSegments=phraseSegments;
phraseSegments=function(s){return oldPhraseSegments(s).flatMap(part=>{const words=part.split(/\s+/);if(words.length<9)return [part];const chunks=[];for(let i=0;i<words.length;i+=5)chunks.push(words.slice(i,i+5).join(' '));return chunks;});};
$('#adultOpen').onclick=adult;
